// Caller: run this first. It lists every person who knows at least one person, with their degree, most connected first.
query people_with_connections() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle
        $p.name
        count(distinct $f) as degree
    }
    order { degree desc }
}
```

```gq
// Caller: run this second. These people know nobody, so the caller gives each a degree of 0 and appends them after the rows from the first query.
query people_with_no_connections() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}
